  app.delete("/api/admin/people/:id", requireAdmin, async (req, res) => {
    {
      const id = String(req.params.id);
      const { partnerEditGate, createPendingChange } = await import("./auth/partnerPermissions");
      const outcome = await partnerEditGate(req, res, "edit_metadata", { kind: "artist", id });
      if (outcome === "deny") return;
      if (outcome === "divert") {
        const row = await createPendingChange({
          targetTable: "people", targetId: id, albumId: null,
          scopeKind: "artist", scopeId: id,
          patch: { __op: "delete" },
          submittedByUserId: req.session.userId!,
        });
        return res.status(202).json({ pendingChange: row, message: "Your edit was sent to GoodTunes for review." });
      }
    }
    await storage.deletePerson(String(req.params.id), req.session.userId ?? null);
    return res.json({ message: "Deleted" });
  });

  // ----- Task #190 — Bands & members ---------------------------------
  // Public reads: a band's roster + the per-album lineup snapshot drive
  // the fan-side artist & album pages, so both are unauthenticated.
  // Writes are admin-only and gated by the same artist-scope edit_metadata
  // permission as PUT /api/admin/people/:id, so an artist-scoped partner
  // can curate their own band's lineup.
  const bandMemberInputToRecord = (b: any) => ({
    roles: Array.isArray(b?.roles)
      ? (b.roles as any[]).map((r) => String(r)).filter((r) => r.trim().length > 0)
      : null,
    joinedYear:
      b?.joinedYear === null || b?.joinedYear === undefined || b?.joinedYear === ""
        ? null
        : Number(b.joinedYear),
    leftYear:
      b?.leftYear === null || b?.leftYear === undefined || b?.leftYear === ""
        ? null
        : Number(b.leftYear),
    displayOrder:
      b?.displayOrder === undefined || b?.displayOrder === null
        ? 0
        : Number(b.displayOrder),
  });

  app.get("/api/people/:id/members", async (req, res) => {
    const rows = await storage.listBandMembers(String(req.params.id));
    return res.json(rows);
  });

  app.get("/api/people/:id/bands", async (req, res) => {
    const rows = await storage.listMemberBands(String(req.params.id));
    return res.json(rows);
  });

  app.get("/api/admin/people/:id/members", requireAdmin, async (req, res) => {
    const rows = await storage.listBandMembers(String(req.params.id));
    return res.json(rows);
  });

  app.post("/api/admin/people/:id/members", requireAdmin, async (req, res) => {
    const bandId = String(req.params.id);
    const memberId = req.body?.memberId ? String(req.body.memberId) : "";
    if (!memberId) {
      return res.status(400).json({ message: "memberId is required" });
    }
    if (memberId === bandId) {
      return res.status(400).json({ message: "A band can't list itself as a member." });
    }
    // Soft-confirm both rows exist; the FK would catch this anyway but
    // the error message is gentler here.
    const [band, member] = await Promise.all([
      storage.getPersonById(bandId),
      storage.getPersonById(memberId),
    ]);
    if (!band) return res.status(404).json({ message: "Band not found" });
    if (!member) return res.status(404).json({ message: "Member not found" });
    const row = await storage.addBandMember({
      bandId,
      memberId,
      ...bandMemberInputToRecord(req.body ?? {}),
    } as any);
    return res.status(201).json(row);
  });

  // ─── Artist buyer roster (admin god-view) ─────────────────────────
  // Returns all fans who bought any album where this person is the
  // primary artist. Admins see full email + name (no PII trimming).
  // Includes headline KPIs (total orders / distinct fans / revenue) and
  // a per-album breakdown, plus a paginated flat order list.
  app.get("/api/admin/people/:id/buyers", requireAdmin, async (req, res) => {
    const personId = String(req.params.id);
    const limit = Math.min(Number(req.query.limit) || 500, 2000);
    const offset = Number(req.query.offset) || 0;
    const albumId = req.query.albumId ? String(req.query.albumId) : null;
    const REVENUE_STATUSES = `'paid','shipped','complete','completed'`;

    // Canonical artist album scope — must stay in lock-step with
    // resolveArtistScope() in server/artistReports.ts so the dashboard
    // lifetime headline and this page's KPIs never drift. An artist owns
    // an album when they are its primaryArtistId OR its payout owner, and
    // the album has not been soft-deleted. (Previously this page scoped by
    // primaryArtistId only, so an album whose payout owner is this person
    // — but whose primary-artist credit is someone else — counted on the
    // dashboard but not here.)
    const artistAlbums = await db.execute<{ id: string; title: string; artwork: string | null }>(sql`
      SELECT id, title, artwork FROM albums
      WHERE (primary_artist_id = ${personId}
             OR (payout_owner_kind = 'person' AND payout_owner_id = ${personId}))
        AND deleted_at IS NULL
      ORDER BY title ASC
    `);
    const albumIds = ((artistAlbums as any).rows ?? []).map((r: any) => r.id as string);

    if (albumIds.length === 0) {
      return res.json({ kpis: { totalOrders: 0, distinctFans: 0, totalCents: 0 }, albums: [], orders: [], total: 0 });
    }

    const { pgArray } = await import("./lib/pgArray");
    const { LOC_CITY, LOC_REGION, LOC_COUNTRY } = await import("./reports/buyers");
    const albumFilter = albumId ? sql`o.album_id = ${albumId}` : sql`o.album_id = ANY(${pgArray(albumIds)})`;

    const [kpisRows, perAlbumRows, orderRows, totalRow] = await Promise.all([
      db.execute<any>(sql`
        SELECT
          COUNT(*)::text AS total_orders,
          COUNT(DISTINCT o.customer_id)::text AS distinct_fans,
          COALESCE(SUM(o.total_cents), 0)::text AS total_cents
        FROM orders o
        WHERE ${albumFilter}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
      `),
      db.execute<any>(sql`
        SELECT a.id AS album_id, a.title, a.artwork,
          COUNT(o.id)::text AS orders,
          COUNT(DISTINCT o.customer_id)::text AS fans,
          COALESCE(SUM(o.total_cents), 0)::text AS revenue_cents
        FROM albums a
        LEFT JOIN orders o ON o.album_id = a.id AND o.status IN (${sql.raw(REVENUE_STATUSES)})
        WHERE a.id = ANY(${pgArray(albumIds)}) AND a.deleted_at IS NULL
        GROUP BY a.id, a.title, a.artwork
        ORDER BY COALESCE(SUM(o.total_cents), 0) DESC NULLS LAST
      `),
      db.execute<any>(sql`
        SELECT o.id, o.created_at, o.status, o.total_cents, o.buyer_name, o.buyer_email,
          o.customer_id, o.album_id, a.title AS album_title,
          ${LOC_CITY} AS city,
          ${LOC_REGION} AS state,
          ${LOC_COUNTRY} AS country,
          cu.email AS fan_email, cu.display_name, cu.real_name
        FROM orders o
        JOIN albums a ON a.id = o.album_id
        LEFT JOIN customer_users cu ON cu.id = o.customer_id
        WHERE ${albumFilter}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
        ORDER BY o.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `),
      db.execute<any>(sql`
        SELECT COUNT(*)::text AS total
        FROM orders o
        WHERE ${albumFilter}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
      `),
    ]);

    const kRow = (kpisRows as any).rows?.[0] ?? {};
    return res.json({
      kpis: {
        totalOrders: Number(kRow.total_orders ?? 0),
        distinctFans: Number(kRow.distinct_fans ?? 0),
        totalCents: Number(kRow.total_cents ?? 0),
      },
      albums: ((perAlbumRows as any).rows ?? []).map((r: any) => ({
        albumId: r.album_id,
        title: r.title,
        artwork: r.artwork,
        orders: Number(r.orders),
        fans: Number(r.fans),
        revenueCents: Number(r.revenue_cents),
      })),
      orders: ((orderRows as any).rows ?? []).map((r: any) => ({
        orderId: r.id,
        createdAt: r.created_at,
        status: r.status,
        totalCents: Number(r.total_cents),
        albumId: r.album_id,
        albumTitle: r.album_title,
        buyerName: r.display_name?.trim() || r.real_name?.trim() || r.buyer_name || null,
        buyerEmail: r.fan_email || r.buyer_email || null,
        customerId: r.customer_id,
        city: r.city,
        state: r.state,
        country: r.country,
      })),
      total: Number(((totalRow as any).rows?.[0]?.total) ?? 0),
    });
  });

  // Per-album full buyer list (admin god-view). Same as above but scoped
  // to a single album — used by AdminAlbumEngagement "View all buyers".
  app.get("/api/admin/albums/:id/buyers", requireAdmin, async (req, res) => {
    const albumId = String(req.params.id);
    const limit = Math.min(Number(req.query.limit) || 200, 2000);
    const offset = Number(req.query.offset) || 0;
    const REVENUE_STATUSES = `'paid','shipped','complete','completed'`;
    const { LOC_CITY, LOC_REGION, LOC_COUNTRY } = await import("./reports/buyers");

    // Task #1499 — server-side search + sort so the Customers tab can
    // filter / order across the WHOLE roster, not just the rows already
    // loaded into the client. Search matches fan name (display/real/buyer
    // snapshot), email (account + buyer snapshot), and shipping city.
    const searchRaw = String(req.query.search ?? "").trim();
    const searchClause = searchRaw
      ? sql` AND (
          cu.display_name ILIKE ${"%" + searchRaw + "%"}
          OR cu.real_name ILIKE ${"%" + searchRaw + "%"}
          OR o.buyer_name ILIKE ${"%" + searchRaw + "%"}
          OR cu.email ILIKE ${"%" + searchRaw + "%"}
          OR o.buyer_email ILIKE ${"%" + searchRaw + "%"}
          OR ${LOC_CITY} ILIKE ${"%" + searchRaw + "%"}
        )`
      : sql``;

    // Task #2645 — "GoodDeed" means the Signed (Printed) cert add-on, not the
    // digital GoodDeed number (every paid copy gets one of those, so the old
    // any-number check read "Yes" for everything). Modern orders carry the
    // flag on order_copies.signed_cert; legacy orders (incl. legacy:gogoods
    // imports) predate per-copy rows, so fall back to the signed_cert add-on
    // line item when the order has no copies at all.
    const hasGoodDeedExpr = sql`(
      EXISTS (
        SELECT 1 FROM order_copies oc
        WHERE oc.order_id = o.id AND oc.signed_cert = TRUE
      )
      OR (
        NOT EXISTS (SELECT 1 FROM order_copies oc2 WHERE oc2.order_id = o.id)
        AND EXISTS (
          SELECT 1 FROM order_items oi
          WHERE oi.order_id = o.id AND oi.kind = 'addon' AND oi.sku = 'signed_cert'
        )
      )
    )`;
    const nameExpr = sql`COALESCE(NULLIF(TRIM(cu.display_name), ''), NULLIF(TRIM(cu.real_name), ''), o.buyer_name, cu.email, o.buyer_email)`;
    const locationExpr = sql`NULLIF(CONCAT_WS(', ', ${LOC_CITY}, ${LOC_REGION}, ${LOC_COUNTRY}), '')`;

    const sortKey = String(req.query.sort ?? "date");
    const dir = String(req.query.dir ?? "").toLowerCase() === "asc";
    const asc = sortKey === "date" ? dir : (req.query.dir ? dir : true);
    const sortDir = asc ? sql.raw("ASC NULLS LAST") : sql.raw("DESC NULLS LAST");
    const orderByCol =
      sortKey === "name"
        ? nameExpr
        : sortKey === "location"
          ? locationExpr
          : sortKey === "gooddeed"
            ? hasGoodDeedExpr
            : sortKey === "amount"
              ? sql`o.total_cents`
              : sql`o.created_at`;
    // Default order (no sort param) preserves the legacy newest-first feed.
    const orderByClause =
      sortKey === "date" && !req.query.dir
        ? sql`ORDER BY o.created_at DESC`
        : sql`ORDER BY ${orderByCol} ${sortDir}, o.created_at DESC`;

    // Task #1504 — CSV export of the WHOLE search/sort-filtered roster (not
    // just the loaded rows). Columns mirror the Customers tab: fan name,
    // email, location, purchase date, GoodDeed, amount.
    //
    // Task #1507 — a `variant=fulfillment` flavour adds the full mailing
    // address captured at checkout (recipient name, line1/line2, city, state,
    // postal code, country) plus an Order type column so operators can ship
    // straight off the export. Digital orders have no shipping snapshot, so
    // their address cells stay blank and Order type reads "Digital".
    if (String(req.query.format ?? "").toLowerCase() === "csv") {
      const fulfillment =
        String(req.query.variant ?? "").toLowerCase() === "fulfillment";
      const exportRows = await db.execute<any>(sql`
        SELECT o.id, o.created_at, o.total_cents, o.buyer_name, o.buyer_email,
          o.shipping_address->>'name' AS ship_name,
          o.shipping_address->>'line1' AS line1,
          o.shipping_address->>'line2' AS line2,
          o.shipping_address->>'city' AS city,
          o.shipping_address->>'state' AS state,
          o.shipping_address->>'postalCode' AS postal_code,
          o.shipping_address->>'country' AS country,
          (o.shipping_address IS NOT NULL) AS has_shipping,
          cu.email AS fan_email, cu.display_name, cu.real_name,
          ${hasGoodDeedExpr} AS has_good_deed
        FROM orders o
        LEFT JOIN customer_users cu ON cu.id = o.customer_id
        WHERE o.album_id = ${albumId}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
          ${searchClause}
        ${orderByClause}
      `);

      const csvCell = (v: unknown) => {
        const s = v == null ? "" : String(v);
        return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
      };
      const truthy = (v: unknown) => v === true || v === "t" || v === "true";
      const header = fulfillment
        ? [
            "Fan",
            "Email",
            "Order type",
            "Recipient",
            "Address line 1",
            "Address line 2",
            "City",
            "State",
            "Postal code",
            "Country",
            "Purchase date",
            "GoodDeed",
            "Amount",
          ]
        : ["Fan", "Email", "Location", "Purchase date", "GoodDeed", "Amount"];
      const lines = [header.join(",")];
      for (const r of ((exportRows as any).rows ?? [])) {
        const name = r.display_name?.trim() || r.real_name?.trim() || r.buyer_name || r.fan_email || r.buyer_email || "Anonymous";
        const email = r.fan_email || r.buyer_email || "";
        const date = r.created_at ? new Date(r.created_at).toISOString().slice(0, 10) : "";
        const goodDeed = truthy(r.has_good_deed) ? "Yes" : "No";
        const amount = (Number(r.total_cents) / 100).toFixed(2);
        if (fulfillment) {
          const isPhysical = truthy(r.has_shipping);
          const recipient = isPhysical ? r.ship_name?.trim() || r.buyer_name || "" : "";
          lines.push(
            [
              name,
              email,
              isPhysical ? "Physical" : "Digital",
              recipient,
              r.line1 || "",
              r.line2 || "",
              r.city || "",
              r.state || "",
              r.postal_code || "",
              r.country || "",
              date,
              goodDeed,
              amount,
            ].map(csvCell).join(","),
          );
        } else {
          const location = [r.city, r.state, r.country].filter(Boolean).join(", ");
          lines.push([name, email, location, date, goodDeed, amount].map(csvCell).join(","));
        }
      }
      // Prepend a UTF-8 BOM so Excel reads accented names correctly.
      const csv = "\uFEFF" + lines.join("\r\n") + "\r\n";
      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="album-${albumId}-${fulfillment ? "fulfillment" : "customers"}.csv"`,
      );
      return res.send(csv);
    }

    const [kpisRows, orderRows, totalRow] = await Promise.all([
      db.execute<any>(sql`
        SELECT
          COUNT(*)::text AS total_orders,
          COUNT(DISTINCT o.customer_id)::text AS distinct_fans,
          COALESCE(SUM(o.total_cents), 0)::text AS total_cents
        FROM orders o
        WHERE o.album_id = ${albumId}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
      `),
      db.execute<any>(sql`
        SELECT o.id, o.created_at, o.status, o.total_cents, o.buyer_name, o.buyer_email,
          o.customer_id,
          ${LOC_CITY} AS city,
          ${LOC_REGION} AS state,
          ${LOC_COUNTRY} AS country,
          cu.email AS fan_email, cu.display_name, cu.real_name,
          ${hasGoodDeedExpr} AS has_good_deed
        FROM orders o
        LEFT JOIN customer_users cu ON cu.id = o.customer_id
        WHERE o.album_id = ${albumId}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
          ${searchClause}
        ${orderByClause}
        LIMIT ${limit} OFFSET ${offset}
      `),
      db.execute<any>(sql`
        SELECT COUNT(*)::text AS total
        FROM orders o
        LEFT JOIN customer_users cu ON cu.id = o.customer_id
        WHERE o.album_id = ${albumId}
          AND o.status IN (${sql.raw(REVENUE_STATUSES)})
          ${searchClause}
      `),
    ]);

    const kRow = (kpisRows as any).rows?.[0] ?? {};
    return res.json({
      kpis: {
        totalOrders: Number(kRow.total_orders ?? 0),
        distinctFans: Number(kRow.distinct_fans ?? 0),
        totalCents: Number(kRow.total_cents ?? 0),
      },
      orders: ((orderRows as any).rows ?? []).map((r: any) => ({
        orderId: r.id,
        createdAt: r.created_at,
        status: r.status,
        totalCents: Number(r.total_cents),
        buyerName: r.display_name?.trim() || r.real_name?.trim() || r.buyer_name || null,
        buyerEmail: r.fan_email || r.buyer_email || null,
        customerId: r.customer_id,
        city: r.city,
        state: r.state,
        country: r.country,
        goodDeed: r.has_good_deed === true || r.has_good_deed === "t" || r.has_good_deed === "true",
      })),
      total: Number(((totalRow as any).rows?.[0]?.total) ?? 0),
    });
  });

  app.put("/api/admin/band-members/:rowId", requireAdmin, async (req, res) => {
    const id = String(req.params.rowId);
    const patch: any = {};
    const b = req.body ?? {};
    if (b.roles !== undefined) {
      patch.roles = Array.isArray(b.roles)
        ? b.roles.map((r: any) => String(r)).filter((r: string) => r.trim().length > 0)
        : null;
    }
    if (b.joinedYear !== undefined) {
      patch.joinedYear =
        b.joinedYear === null || b.joinedYear === "" ? null : Number(b.joinedYear);
    }
    if (b.leftYear !== undefined) {
      patch.leftYear =
        b.leftYear === null || b.leftYear === "" ? null : Number(b.leftYear);
    }
    if (b.displayOrder !== undefined) {
      patch.displayOrder = Number(b.displayOrder);
    }
    const row = await storage.updateBandMember(id, patch);
    if (!row) return res.status(404).json({ message: "Band member not found" });
    return res.json(row);
  });

  app.delete("/api/admin/band-members/:rowId", requireAdmin, async (req, res) => {
    await storage.removeBandMember(String(req.params.rowId), req.session.userId ?? null);
    return res.json({ message: "Deleted" });
  });

  // ----- Album lineup snapshots -------------------------------------
  app.get("/api/albums/:id/lineup", async (req, res) => {
    const rows = await storage.listAlbumLineup(String(req.params.id));
    return res.json(rows);
  });

  app.get("/api/admin/albums/:id/lineup", requireAdmin, async (req, res) => {
    const rows = await storage.listAlbumLineup(String(req.params.id));
    return res.json(rows);
  });

  // Task #193 — Proposed lineup rolled up from per-track SuperCredits.
  // Returns distinct performers across the album's tracks, ordered by
  // how many tracks they played on. The UI accepts (or edits) the
  // proposal in one click and writes via PUT /api/admin/albums/:id/lineup.
  app.get("/api/admin/albums/:id/lineup/suggest", requireAdmin, async (req, res) => {
    const rows = await storage.suggestAlbumLineupFromCredits(String(req.params.id));
    return res.json(rows);
  });

  // Full-replace semantics — admin always saves the entire ordered list.
  // Body: { members: [{ memberId, roles?: string[]|null, displayOrder?: number }, ...] }
  app.put("/api/admin/albums/:id/lineup", requireAdmin, async (req, res) => {
    const albumId = String(req.params.id);
    const input = Array.isArray(req.body?.members) ? req.body.members : [];
    const seen = new Set<string>();
    const members: Array<{ memberId: string; roles: string[] | null; displayOrder: number }> = [];
    for (let i = 0; i < input.length; i++) {
      const m = input[i] ?? {};
      const memberId = m.memberId ? String(m.memberId) : "";
      if (!memberId || seen.has(memberId)) continue;
      seen.add(memberId);
      members.push({
        memberId,
        roles: Array.isArray(m.roles)
          ? m.roles.map((r: any) => String(r)).filter((r: string) => r.trim().length > 0)
          : null,
        displayOrder: m.displayOrder === undefined ? i : Number(m.displayOrder),
      });
    }
    const rows = await storage.setAlbumLineup(albumId, members);
    return res.json(rows);
  });

  app.delete("/api/admin/albums/:id/lineup", requireAdmin, async (req, res) => {
    await storage.clearAlbumLineup(String(req.params.id));
    return res.json({ message: "Cleared" });
  });

  // --- Artist URL scraper (Apple Music / Spotify → prefilled person + discography) ---
  // Mirror of the instrument scraper. Two sources:
  //   1. The artist page itself: OG meta for image + bio snippet (and canonical
  //      name from <title> / og:title). Works on both services.
  //   2. iTunes Lookup API (free, no auth) — Apple Music URLs end in a numeric
  //      artist id, which we feed to lookup?id=...&entity=album to get the
  //      artist's complete discography with artwork + year + track count. We
  //      surface that as a "Discography" panel so the admin can one-click
  //      add real albums (with real artwork) to the GoodTunes catalog.
  // Per replit.md: we host the song in-app for ~2 weeks then send fans back
  // to Apple/Spotify via these same URLs ("referring them to give them
  // business"). One paste fills both jobs.
  const handlePersonScrape = async (req: Request, res: Response) => {
    const url = String(req.body?.url ?? "").trim();
    if (!url || !/^https?:\/\//i.test(url)) {
      return res.status(400).json({ message: "A full https:// artist URL is required" });
    }
    let parsed: URL;
    try { parsed = new URL(url); } catch { return res.status(400).json({ message: "Malformed URL" }); }
    const host = parsed.hostname.replace(/^www\./, "");

    // Detect service. Apple Music artist URLs look like
    //   /<country>/artist/<slug>/<numeric-id>(?i=...)?
    // Spotify artist URLs look like /artist/<base62>
    // Bandcamp = anything on `<artist>.bandcamp.com` or bandcamp.com itself.
    // Anything else is treated as a generic bio page (Person JSON-LD + OG
    // fallback) — the catch-all for vendor staff pages, label team pages,
    // wikipedia-style profiles, etc.
    let source: "apple" | "spotify" | "bandcamp" | "generic" = "generic";
    let itunesArtistId: string | null = null;
    if (/(^|\.)music\.apple\.com$/.test(host)) {
      source = "apple";
      const m = parsed.pathname.match(/\/artist\/(?:[^/]+\/)?(\d+)/i);
      if (m) itunesArtistId = m[1];
    } else if (/(^|\.)open\.spotify\.com$/.test(host) || /(^|\.)spotify\.com$/.test(host)) {
      source = "spotify";
    } else if (/(^|\.)bandcamp\.com$/.test(host) || host === "bandcamp.com") {
      source = "bandcamp";
    }

    // -------- Generic / Bandcamp branch ---------------------------------
    // Reuses the same OG + JSON-LD shape the instrument scraper uses but
    // looks for Person / MusicGroup nodes instead of Product. Returns the
    // unified prefill shape { name, title, bio, photoUrl, links[] }.
    if (source === "generic" || source === "bandcamp") {
      try {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), 10_000);
        const html = await safeFetchWithUaFallback(url, { signal: ctrl.signal })
          .then((r) => {
            if (!r.ok) throw new Error(`Page returned ${r.status}`);
            return r.text();
          })
          .finally(() => clearTimeout(t));

        const meta: Record<string, string> = {};
        const re1 = /<meta[^>]+(?:property|name)=["']([^"']+)["'][^>]+content=["']([^"']*)["'][^>]*>/gi;
        const re2 = /<meta[^>]+content=["']([^"']*)["'][^>]+(?:property|name)=["']([^"']+)["'][^>]*>/gi;
        let m: RegExpExecArray | null;
        while ((m = re1.exec(html))) { const k = m[1].toLowerCase(); if (!(k in meta)) meta[k] = decodeEntities(m[2]); }
        while ((m = re2.exec(html))) { const k = m[2].toLowerCase(); if (!(k in meta)) meta[k] = decodeEntities(m[1]); }

        const person = pickPerson(html);

        // Name: JSON-LD wins. OG title strips trailing " | <site>" suffix
        // (Bandcamp's "<Artist> | <Artist>" → "<Artist>"; LinkedIn-style).
        let name: string | null = null;
        if (person?.name) name = String(person.name).trim();
        else if (meta["og:title"]) name = meta["og:title"];
        else if (meta["twitter:title"]) name = meta["twitter:title"];
        if (name) name = name.replace(/\s*[|·\-–—]\s*[^|·\-–—]{1,40}$/u, "").trim() || name;

        // Title / role — JSON-LD jobTitle (vendor team pages), Bandcamp's
        // "location" tag as a soft fallback. OG doesn't carry a role.
        let title: string | null = null;
        if (person?.jobTitle) title = String(person.jobTitle).trim();
        else if (person?.affiliation?.name) title = String(person.affiliation.name).trim();

        // Bio — JSON-LD description (rich), OG description (always short),
        // <meta name=description> (always short). Strip HTML.
        let bio: string | null = null;
        const rawBio =
          person?.description ||
          meta["og:description"] ||
          meta["twitter:description"] ||
          meta["description"] ||
          null;
        if (rawBio) bio = cleanBioText(String(rawBio)) || null;

        // Image — JSON-LD image can be { @type: ImageObject, url } or a
        // bare URL or an array. Same picker the instrument scraper uses.
        const pickImage = (img: any): string | null => {
          if (!img) return null;
          if (typeof img === "string") return img;
          if (Array.isArray(img)) {
            for (const x of img) { const v = pickImage(x); if (v) return v; }
            return null;
          }
          if (typeof img === "object") return img.url || img.contentUrl || null;
          return null;
        };
        let rawImage: string | null =
          pickImage(person?.image) ||
          meta["og:image:secure_url"] || meta["og:image"] || meta["twitter:image"] ||
          null;
        if (rawImage?.startsWith("//")) rawImage = `https:${rawImage}`;
        if (rawImage?.startsWith("/")) rawImage = `${parsed.origin}${rawImage}`;

        // Links — JSON-LD sameAs[] is the standard, plus the scrape URL
        // itself classified by host (a Bandcamp page → websiteUrl). Dedup
        // by kind, first-write-wins.
        const links: Array<{ kind: string; url: string }> = [];
        const seenKinds = new Set<string>();
        const pushLink = (raw: string) => {
          const cl = classifyPersonLink(raw);
          if (!cl) return;
          if (seenKinds.has(cl.kind)) return;
          seenKinds.add(cl.kind);
          links.push(cl);
        };
        const sameAs = person?.sameAs;
        if (Array.isArray(sameAs)) {
          for (const s of sameAs) {
            if (typeof s === "string") pushLink(s);
          }
        } else if (typeof sameAs === "string") {
          pushLink(sameAs);
        }
        // Bandcamp + generic: also include the original URL so the admin
        // keeps the breadcrumb back to where the bio came from.
        pushLink(url);

        // Image must land in Object Storage — GoodTunes never hot-links a
        // scraped photo (capabilities + asset-ownership rule). If the
        // rehost fails we drop the photo entirely and let the admin set
        // one by hand; the rest of the prefill still ships.
        let photoUrl: string | null = null;
        if (rawImage) {
          try { photoUrl = await rehostRemoteImage(rawImage); }
          catch { photoUrl = null; }
        }

        // No-person guard. A page with no name is not a Person page — bail
        // with the structured 422 the UI uses to render its inline
        // fallback copy. Apart from missing a name, we also bail if we
        // got nothing else worth keeping (no bio, no photo, no extra
        // links beyond the URL the operator pasted).
        if (!name) {
          return res.status(422).json({
            source,
            message: "Couldn't find a person at that URL — fill in the fields below.",
          });
        }
        if (!bio && !photoUrl && links.length <= 1) {
          return res.status(422).json({
            source,
            message: "Couldn't find a person at that URL — fill in the fields below.",
          });
        }

        return res.json({
          source,
          name,
          title,
          bio,
          photoUrl,
          links,
          // Legacy fields kept for shape compatibility with the existing
          // Apple/Spotify response — null when not applicable.
          itunesArtistId: null,
          appleMusicUrl: null,
          spotifyUrl: null,
          albums: [],
        });
      } catch (e: any) {
        const msg = e?.name === "AbortError"
          ? "Page took too long to respond."
          : (e?.message || "Unable to read that page");
        return res.status(502).json({ source, message: msg });
      }
    }

    try {
      // ----- 1) Scrape the artist page for OG image + bio snippet -----
      let metaName: string | null = null;
      let bio: string | null = null;
      let rawImage: string | null = null;
      try {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), 10_000);
        const html = await safeFetch(url, {
          signal: ctrl.signal,
          headers: {
            "User-Agent": "Mozilla/5.0 (compatible; GoodTunesBot/1.0; +https://goodtunes.app)",
            "Accept": "text/html,application/xhtml+xml",
          },
        }).then((r) => {
          if (!r.ok) throw new Error(`Page returned ${r.status}`);
          return r.text();
        }).finally(() => clearTimeout(t));

        const meta: Record<string, string> = {};
        const re1 = /<meta[^>]+(?:property|name)=["']([^"']+)["'][^>]+content=["']([^"']*)["'][^>]*>/gi;
        const re2 = /<meta[^>]+content=["']([^"']*)["'][^>]+(?:property|name)=["']([^"']+)["'][^>]*>/gi;
        let m: RegExpExecArray | null;
        while ((m = re1.exec(html))) {
          const key = m[1].toLowerCase();
          if (!(key in meta)) meta[key] = decodeEntities(m[2]);
        }
        while ((m = re2.exec(html))) {
          const key = m[2].toLowerCase();
          if (!(key in meta)) meta[key] = decodeEntities(m[1]);
        }

        // Apple titles its og:title as "Artist Name on Apple Music" — strip
        // the trailing service tag. Spotify is "Artist Name | Spotify".
        let ogTitle = meta["og:title"] || meta["twitter:title"] || null;
        if (ogTitle) {
          ogTitle = ogTitle
            .replace(/\s+on Apple Music\s*$/i, "")
            .replace(/\s*[|·]\s*Spotify\s*$/i, "")
            .trim();
        }
        metaName = ogTitle;
        bio = meta["og:description"] || meta["twitter:description"] || meta["description"] || null;
        // Spotify's OG description for every artist page is boilerplate —
        // "Artist · 40.8K monthly listeners." — not the actual About text
        // (which they lazy-load via internal GraphQL and is unavailable in
        // the initial HTML). Reject the pattern so we don't pollute the
        // admin's BIO field with a listener count. Apple Music's
        // og:description is usually the real artist blurb, so we keep it.
        if (bio && /^artist\s*[·•|-]\s*[\d.,]+\s*[kmb]?\s*monthly listeners\.?$/i.test(bio.trim())) {
          bio = null;
        }
        // Apple Music's og:description is usually the real artist blurb, but
        // frequently it's just "Listen to music by <Artist> on Apple Music."
        // Every other scraper (generic person, label, vendor, plant,
        // fulfillment) routes the bio through this helper; the streaming-
        // artist path never did, so the boilerplate reached the admin BIO
        // field raw. Strip it here too — collapse to null if nothing of
        // substance survives.
        if (bio) {
          bio = stripAppleMusicBoilerplate(bio) || null;
        }
        rawImage = meta["og:image:secure_url"] || meta["og:image"] || meta["twitter:image"] || null;
        if (rawImage?.startsWith("//")) rawImage = `https:${rawImage}`;
        if (rawImage?.startsWith("/")) rawImage = `${parsed.origin}${rawImage}`;
        // Apple Music's og:image is the wide 1200×630 share card — a small
        // circular portrait centered on a white background. Dropped into a
        // circular avatar (PersonPreviewCard, PerformerSheet) it shows up
        // as a tiny photo ringed by a huge white border. Apple's image CDN
        // (mzstatic.com) re-encodes the same source at any size + crop
        // suffix encoded in the final path segment: e.g.
        //   .../1200x630cw.jpg  (crop-wide, white padded)
        //   .../600x600bb.png   (bounding box, no padding)
        //   .../400x400cc.jpg   (center crop)
        //   .../800x800sr.jpg   (stretch)
        //   .../1200x1200fc.jpg (face crop)
        // Normalize *any* recognized size+suffix variant to a square
        // 1200×1200bb so we always get a tight, padding-free portrait.
        // We match on `WxHxx.ext` (2 letters before the extension) instead
        // of a hard-coded suffix so future Apple suffixes still get
        // normalized. The query string is preserved.
        if (
          source === "apple" &&
          rawImage &&
          /mzstatic\.com\//.test(rawImage)
        ) {
          rawImage = rawImage.replace(
            /\/\d+x\d+[a-z]{2}\.(jpg|jpeg|png|webp)(\?.*)?$/i,
            "/1200x1200bb.$1$2",
          );
        }
      } catch {
        /* OG scrape is best-effort — Apple sometimes 403s the bot. We still
           have iTunes Lookup below to fill name + first album art. */
      }

      // ----- 2) Apple-only: pull the canonical artist + full discography -----
      let canonicalName: string | null = null;
      let albums: Array<{
        collectionId: number;
        name: string;
        artworkUrl: string;
        year: number | null;
        trackCount: number | null;
        type: "album" | "EP";
        releaseDate: string | null;
      }> = [];
      if (source === "apple" && itunesArtistId) {
        try {
          const lookup = await safeFetch(
            `https://itunes.apple.com/lookup?id=${itunesArtistId}&entity=album&limit=200&country=us`,
            { headers: { "Accept": "application/json" } },
          ).then((r) => r.json() as Promise<{ results: any[] }>);
          const results = Array.isArray(lookup?.results) ? lookup.results : [];
          const artistRow = results.find((r) => r.wrapperType === "artist");
          canonicalName = artistRow?.artistName || null;
          albums = results
            .filter((r) => r.wrapperType === "collection")
            .map((r) => {
              // iTunes returns 100×100 thumbs by default — swap to 600×600
              // which is what Apple Music UI actually uses.
              const art100: string = r.artworkUrl100 || r.artworkUrl60 || "";
              const artworkUrl = art100.replace(/\/(\d+)x(\d+)bb\.(jpg|png)$/i, "/600x600bb.$3");
              const releaseDate: string | null = r.releaseDate || null;
              const year = releaseDate ? Number(releaseDate.slice(0, 4)) || null : null;
              const trackCount = Number(r.trackCount) || null;
              return {
                collectionId: Number(r.collectionId),
                name: String(r.collectionName || ""),
                artworkUrl,
                year,
                trackCount,
                type: (trackCount && trackCount <= 6 ? "EP" : "album") as "album" | "EP",
                releaseDate,
                // Canonical Apple Music album URL — the "Listen on Apple
                // Music" handoff target. Spotify equivalent has to be set
                // manually for now (no free cross-service mapping).
                appleMusicUrl: (r.collectionViewUrl as string) || null,
              };
            })
            // newest first — matches the canvas order of an Apple Music artist page
            .sort((a, b) => (b.releaseDate || "").localeCompare(a.releaseDate || ""));
        } catch {
          /* discography is a bonus — don't fail the whole scrape if iTunes
             is down or rate-limits us */
        }
      }

      // ----- 3) Rehost photo so we don't depend on Apple's CDN long-term -----
      // Photo must land in Object Storage — GoodTunes never hot-links a
      // scraped photo. If the rehost fails we drop the photo entirely
      // and let the admin set one by hand.
      let photoUrl: string | null = null;
      if (rawImage) {
        try { photoUrl = await rehostRemoteImage(rawImage); }
        catch { photoUrl = null; }
      }

      const name = canonicalName || metaName || null;
      // Build a links[] payload for shape parity with the generic branch
      // so the client can iterate one list regardless of source. Apple
      // and Spotify each carry their canonical own-URL plus, for Apple,
      // a Spotify cross-link is never available (no free mapping).
      const links: Array<{ kind: string; url: string }> = [];
      if (source === "apple") links.push({ kind: "appleMusicUrl", url });
      if (source === "spotify") links.push({ kind: "spotifyUrl", url });
      res.json({
        source,
        name,
        title: null,
        photoUrl,
        bio,
        itunesArtistId,
        appleMusicUrl: source === "apple" ? url : null,
        spotifyUrl: source === "spotify" ? url : null,
        links,
        albums,
      });
    } catch (e: any) {
      const msg = e?.name === "AbortError" ? "Streaming page took too long to respond." : (e?.message || "Unable to read that page");
      res.status(502).json({ message: msg });
    }
  };
  app.post("/api/admin/people/scrape", requireAdminBearer, handlePersonScrape);
  // Task #2253 — press portal paste-a-URL scrape. Same prefill logic, gated to
  // the press scope (Owner/Admin) so the God-View Add Person dialog works in
  // the Press portal without touching the /api/admin/people deny wall.
  app.post(
    "/api/press/:id/people/scrape",
    requireAdmin,
    requirePressScopeRoute,
    requirePressEditorRoute,
    handlePersonScrape,
  );

  // ----- SuperCredits™ catalog: Instruments + vendors ----------------------
  app.get("/api/instruments", async (req, res) => {
    // Admins (CMS) see every vendor — hidden ones still need to be editable.
    // Fans see the public set only.
    const includeHiddenVendors = await isAdminUser(req);
    const instruments = await storage.getInstruments({ includeHiddenVendors });
    // Artist admins see only instruments credited on their own albums/songs.
    const callerRoleInstr = req.session?.userId
      ? await getUserRole(req.session.userId)
      : null;
    if (callerRoleInstr?.role === "artist" && !callerRoleInstr.roleScopeId) return res.json([]);
    if (callerRoleInstr?.role === "artist" && callerRoleInstr.roleScopeId) {
      const artistPid = callerRoleInstr.roleScopeId;
      const albumRows = await db.execute<{ id: string }>(sql`
        SELECT id FROM albums
        WHERE (primary_artist_id = ${artistPid}
               OR (payout_owner_kind = 'person' AND payout_owner_id = ${artistPid}))
          AND deleted_at IS NULL
      `);
      const artistAlbumIds: string[] = (albumRows as any).rows?.map((r: any) => r.id) ?? [];
      if (artistAlbumIds.length) {
        const instrIds = await db.execute<{ instrument_id: string }>(sql`
          SELECT DISTINCT tp.instrument_id FROM track_performers tp
          JOIN songs s ON s.id = tp.song_id
          WHERE s.album_id = ANY(${pgArray(artistAlbumIds)}) AND tp.instrument_id IS NOT NULL
        `);
        const scopedIds = new Set(
          (instrIds as any).rows?.map((r: any) => String(r.instrument_id)) ?? [],
        );
        return res.json(instruments.filter((i) => scopedIds.has(i.id)));
      }
      // Artist has no albums yet — return empty list.
      return res.json([]);
    }
    return res.json(instruments);
  });
  app.get("/api/instruments/:id", async (req, res) => {
    const includeHiddenVendors = await isAdminUser(req);
    const i = await storage.getInstrumentById(String(req.params.id), { includeHiddenVendors });
    if (!i) return res.status(404).json({ message: "Instrument not found" });
    return res.json(i);
  });
  app.post("/api/admin/instruments", requireAdmin, async (req, res) => {
    const { name, category, shortCategory, photoUrl, about, artistNote, makerVendorId, sourceUrl, galleryImageUrls } = req.body ?? {};
    if (!name || !category) return res.status(400).json({ message: "name and category are required" });
    if (shortCategory && !(SHORT_CATEGORIES as readonly string[]).includes(String(shortCategory))) {
      return res.status(400).json({ message: `Invalid shortCategory. Allowed: ${SHORT_CATEGORIES.join(", ")}` });
    }
    // Task #174 — validate the Maker FK up front so we return 400 instead
    // of letting Postgres raise a generic 500 on FK violation. Empty
    // string clears the link.
    if (makerVendorId) {
      const m = await storage.getVendorById(String(makerVendorId));
      if (!m) return res.status(400).json({ message: "makerVendorId does not match any vendor" });
    }
    // Task #461 — light shape check; we don't want a stray "Carter
    // Vintage Guitar" string landing in a URL column. Empty/missing is
    // allowed (blank-shell creates have no source page).
    let sourceUrlClean: string | null = null;
    if (sourceUrl !== undefined && sourceUrl !== null && String(sourceUrl).trim() !== "") {
      const s = String(sourceUrl).trim();
      if (!/^https?:\/\//i.test(s)) {
        return res.status(400).json({ message: "sourceUrl must start with http:// or https://" });
      }
      sourceUrlClean = s;
    }
    // Task #1233 — extra gallery photos picked in the Add-gear preview.
    // The client sends RAW source URLs (the scrape only rehosts the hero);
    // rehost each into Object Storage like the primary, best-effort with a
    // hot-link fallback so a single bad image never sinks the whole import.
    // Dedupe + drop anything equal to the already-stored primary photoUrl.
    let photoUrlsClean: string[] | null = null;
    if (Array.isArray(galleryImageUrls) && galleryImageUrls.length > 0) {
      const primary = photoUrl ? String(photoUrl) : null;
      const raws = dedupeImageUrls(
        galleryImageUrls.map((u: any) => normalizeImageUrl(u)),
      ).filter((u) => u !== primary);
      const hosted: string[] = [];
      for (const raw of raws) {
        try { hosted.push(await rehostRemoteImage(raw)); }
        catch { hosted.push(raw); /* hot-link fallback, operator can re-fetch */ }
      }
      if (hosted.length > 0) photoUrlsClean = hosted;
    }
    const i = await storage.createInstrument({
      name: String(name),
      category: String(category),
      shortCategory: shortCategory ? String(shortCategory) : null,
      photoUrl: photoUrl ? String(photoUrl) : null,
      photoUrls: photoUrlsClean,
      about: about ? String(about) : null,
      artistNote: artistNote ? String(artistNote) : null,
      makerVendorId: makerVendorId ? String(makerVendorId) : null,
      sourceUrl: sourceUrlClean,
    } as any);
    return res.status(201).json(i);
  });
  app.put("/api/admin/instruments/:id", requireAdmin, async (req, res) => {
    const id = String(req.params.id);
    const { name, category, shortCategory, photoUrl, photoUrls, about, artistNote, makerVendorId, sourceUrl } = req.body ?? {};
    const updates: any = {};
    if (name !== undefined) updates.name = String(name);
    if (category !== undefined) updates.category = String(category);
    if (shortCategory !== undefined) {
      if (shortCategory && !(SHORT_CATEGORIES as readonly string[]).includes(String(shortCategory))) {
        return res.status(400).json({ message: `Invalid shortCategory. Allowed: ${SHORT_CATEGORIES.join(", ")}` });
      }
      updates.shortCategory = shortCategory ? String(shortCategory) : null;
    }
    if (photoUrl !== undefined) updates.photoUrl = photoUrl ? String(photoUrl) : null;
    // Task #1233 — gallery edit. Accepts an array of already-hosted URLs
    // (operator reorder/remove in the PhotoPanel); null/empty clears it.
    // These are stored verbatim — no rehosting on PUT, since they're
    // already Object-Storage URLs from the import.
    if (photoUrls !== undefined) {
      if (!photoUrls || (Array.isArray(photoUrls) && photoUrls.length === 0)) {
        updates.photoUrls = null;
      } else if (Array.isArray(photoUrls)) {
        const cleaned = dedupeImageUrls(photoUrls.map((u: any) => normalizeImageUrl(u)));
        updates.photoUrls = cleaned.length > 0 ? cleaned : null;
      }
    }
    if (about !== undefined) updates.about = about ? String(about) : null;
    if (artistNote !== undefined) updates.artistNote = artistNote ? String(artistNote) : null;
    // Task #461 — empty string clears the breadcrumb; non-empty must
    // look like a URL.
    if (sourceUrl !== undefined) {
      if (sourceUrl === null || sourceUrl === "") {
        updates.sourceUrl = null;
      } else {
        const s = String(sourceUrl).trim();
        if (!s) {
          updates.sourceUrl = null;
        } else if (!/^https?:\/\//i.test(s)) {
          return res.status(400).json({ message: "sourceUrl must start with http:// or https://" });
        } else {
          updates.sourceUrl = s;
        }
      }
    }
    // Task #174 — headline maker. `null` / `""` clears the link; a real
    // id is validated against vendors so a bad id returns 400 not 500.
    if (makerVendorId !== undefined) {
      if (makerVendorId === null || makerVendorId === "") {
        updates.makerVendorId = null;
      } else {
        const m = await storage.getVendorById(String(makerVendorId));
        if (!m) return res.status(400).json({ message: "makerVendorId does not match any vendor" });
        updates.makerVendorId = String(makerVendorId);
      }
    }
    const i = await storage.updateInstrument(id, updates);
    if (!i) return res.status(404).json({ message: "Instrument not found" });
    return res.json(i);
  });
  app.get("/api/admin/instruments/:id/usage", requireAdmin, async (req, res) => {
    return res.json(await storage.getInstrumentUsage(String(req.params.id)));
  });
  app.delete("/api/admin/instruments/:id", requireAdmin, async (req, res) => {
    await storage.deleteInstrument(String(req.params.id), req.session.userId ?? null);
    return res.json({ message: "Deleted" });
  });

  // Task #461 — re-run the rehost step against the instrument's stored
  // `sourceUrl`. Pulls the page, picks the same image the scraper would
  // (JSON-LD Product.image → og:image → twitter:image → bare `image`),
  // rehosts into Object Storage, writes the new url onto `photoUrl`.
  // One-click recovery for the "Martin D-28 photo went missing" case
  // once an operator has filled in the source page.
  app.post("/api/admin/instruments/:id/refetch-image", requireAdmin, async (req, res) => {
    const id = String(req.params.id);
    const inst = await storage.getInstrumentById(id);
    if (!inst) return res.status(404).json({ message: "Instrument not found" });
    const src = (inst as any).sourceUrl as string | null;
    if (!src) return res.status(400).json({ message: "No source URL on this gear — set one first." });
    let parsed: URL;
    try { parsed = new URL(src); } catch { return res.status(400).json({ message: "Stored source URL is malformed." }); }
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), 10_000);
      const html = await safeFetchWithUaFallback(src, { signal: ctrl.signal })
        .then((r) => {
          if (!r.ok) throw new Error(`Source page returned ${r.status}`);
          return r.text();
        })
        .finally(() => clearTimeout(t));
      // Same meta-tag harvest the scrape route uses — kept short here
      // since we only need image-related keys.
      const meta: Record<string, string> = {};
      const re1 = /<meta[^>]+(?:property|name)=["']([^"']+)["'][^>]+content=["']([^"']*)["'][^>]*>/gi;
      const re2 = /<meta[^>]+content=["']([^"']*)["'][^>]+(?:property|name)=["']([^"']+)["'][^>]*>/gi;
      let m: RegExpExecArray | null;
      while ((m = re1.exec(html))) { const k = m[1].toLowerCase(); if (!(k in meta)) meta[k] = decodeEntities(m[2]); }
      while ((m = re2.exec(html))) { const k = m[2].toLowerCase(); if (!(k in meta)) meta[k] = decodeEntities(m[1]); }
      const product = pickProduct(html, meta["og:site_name"] || null);
      const pickImage = (img: any): string | null => {
        if (!img) return null;
        if (typeof img === "string") return img;
        if (Array.isArray(img)) { for (const x of img) { const v = pickImage(x); if (v) return v; } return null; }
        if (typeof img === "object") return img.url || img.contentUrl || null;
        return null;
      };
      let rawImage: string | null =
        pickImage(product?.image) ||
        meta["og:image:secure_url"] || meta["og:image"] || meta["twitter:image"] || meta["image"] || null;
      if (rawImage?.startsWith("//")) rawImage = `https:${rawImage}`;
      if (rawImage?.startsWith("/")) rawImage = `${parsed.origin}${rawImage}`;
      if (!rawImage) return res.status(422).json({ message: "Couldn't find an image on that page." });
      const rehosted = await rehostRemoteImage(rawImage);
      const updated = await storage.updateInstrument(id, { photoUrl: rehosted } as any);
      return res.json({ photoUrl: rehosted, instrument: updated });
    } catch (e: any) {
      const msg = e?.name === "AbortError" ? "Source page took too long to respond." : (e?.message || "Couldn't refetch the image.");
      return res.status(502).json({ message: msg });
    }
  });

  // Task #461 — one-shot idempotent backfill. For every instrument that
  // has no `sourceUrl` *and* exactly one `instrument_vendors` row, copy
  // that row's `affiliateUrl` into `sourceUrl`. Multi-reseller pieces
  // stay untouched — picking the "right" listing is too ambiguous to
  // automate. Safe to re-run; only rows still missing a sourceUrl get
  // touched.
  app.post("/api/admin/instruments/backfill-source-url", requireAdmin, async (_req, res) => {
    try {
      // Tightened per code review: require EXACTLY one
      // `instrument_vendors` row total (not "one with a non-empty
      // affiliate_url"), so a piece with three resellers where only
      // one happens to have a URL isn't silently treated as
      // single-source. The single row must also carry a usable URL.
      const result = await db.execute(sql`
        WITH vendor_counts AS (
          SELECT instrument_id, COUNT(*) AS n,
                 MIN(affiliate_url) AS affiliate_url
          FROM instrument_vendors
          GROUP BY instrument_id
          HAVING COUNT(*) = 1
        )
        UPDATE instruments i
        SET source_url = vc.affiliate_url
        FROM vendor_counts vc
        WHERE i.id = vc.instrument_id
          AND i.source_url IS NULL
          AND vc.affiliate_url IS NOT NULL
          AND vc.affiliate_url <> ''
        RETURNING i.id;
      `);
      const updated = Array.isArray((result as any).rows) ? (result as any).rows.length : 0;
      console.log(`[task-461] backfilled source_url on ${updated} instruments`);
      return res.json({ updated });
    } catch (e: any) {
      return res.status(500).json({ message: e?.message || "Backfill failed" });
    }
  });

  // ----- Vendor entity CRUD ----------------------------------------------
  // A `vendor` is one real-world shop (Carter, Reverb, Sweetwater, …).
  // ----- Label ENTITY routes ----------------------------------------------
  // Public reads + admin CRUD. Each album.labelId points at one of these.
  app.get("/api/labels", async (_req, res) => {
    return res.json(await storage.getLabels());
  });
  app.get("/api/labels/:id", async (req, res) => {
    const l = await storage.getLabelById(String(req.params.id));
    if (!l) return res.status(404).json({ message: "Label not found" });
    return res.json(l);
  });
  app.post("/api/admin/labels", requireAdmin, async (req, res) => {
    const { name, domain, logoUrl, bio, location, websiteUrl, instagramUrl, coverUrl } = req.body ?? {};
    if (!name) return res.status(400).json({ message: "name is required" });
    const normDomain = domain
      ? String(domain).toLowerCase().replace(/^www\./, "")
      : null;
    // Mirror the vendors flow: when a domain is supplied, surface an
    // existing label with that domain as a 409 (+ the row), so the admin
    // UI can offer "open existing" instead of silently double-creating.
    if (normDomain) {
      const existing = await storage.getLabelByDomain(normDomain);
      if (existing) {
        return res
          .status(409)
          .json({ message: "A label with that domain already exists", label: existing });
      }
    }
    try {
      const l = await storage.createLabel({
        name: String(name),
        domain: normDomain,
        logoUrl: logoUrl ? String(logoUrl) : null,
        bio: bio ? String(bio) : null,
        location: location ? String(location) : null,
        websiteUrl: websiteUrl ? String(websiteUrl) : null,
        instagramUrl: instagramUrl ? String(instagramUrl) : null,
        coverUrl: coverUrl ? String(coverUrl) : null,
      });
      return res.status(201).json(l);
    } catch (err: any) {
      // Task #1254 — map a race on the labels.domain partial unique index
      // to a friendly 409 instead of a raw 500 (mirrors manufacturers/vendors).
      if (err?.code === "23505") {
        return res.status(409).json({ message: "A label with that domain already exists" });
      }
      throw err;
    }
  });
  app.put("/api/admin/labels/:id", requireAdmin, async (req, res) => {
    const id = String(req.params.id);
    // Task #79 — label-scoped partners editing their own label profile
    // (bio, logo, links) need edit_metadata. No album lock — labels
    // aren't sold — but approval-mode still diverts to the queue.
    {
      const { partnerEditGate, createPendingChange } = await import("./auth/partnerPermissions");
      const outcome = await partnerEditGate(req, res, "edit_metadata", { kind: "label", id });
      if (outcome === "deny") return;
      if (outcome === "divert") {
        const row = await createPendingChange({
          targetTable: "labels", targetId: id, albumId: null,
          scopeKind: "label", scopeId: id,
          patch: { __op: "update", ...(req.body ?? {}) },
          submittedByUserId: req.session.userId!,
        });
        return res.status(202).json({ pendingChange: row, message: "Your edit was sent to GoodTunes for review." });
      }
    }
    const { name, domain, logoUrl, bio, location, websiteUrl, instagramUrl, coverUrl } = req.body ?? {};
    const updates: any = {};
    if (name !== undefined) updates.name = String(name);
    if (domain !== undefined) {
      updates.domain = domain
        ? String(domain).toLowerCase().replace(/^www\./, "")
        : null;
    }
    if (logoUrl !== undefined) updates.logoUrl = logoUrl ? String(logoUrl) : null;
    // Curation lock on the label logo. Loose-coerce so callers can pass
    // boolean | "true" | "false". Locking does NOT prevent a same-PUT
    // logoUrl write — locks gate *automated* refresh paths, not the
    // admin's own Replace upload. The UI dims the dropzone when locked
    // as a usability nudge. Mirrors the Person lock pattern.
    if (req.body?.logoLocked !== undefined) {
      updates.logoLocked = !(req.body.logoLocked === false || req.body.logoLocked === "false");
    }
    if (bio !== undefined) updates.bio = bio ? String(bio) : null;
    if (location !== undefined) updates.location = location ? String(location) : null;
    // Task #489 — structured snapshot persisted next to the free-text
    // `location`. Pass through as-is so the jsonb column carries the
    // exact PartnerAddressSnapshot the autocomplete emitted.
    if (req.body?.locationAddress !== undefined) {
      updates.locationAddress = req.body.locationAddress ?? null;
    }
    if (websiteUrl !== undefined) updates.websiteUrl = websiteUrl ? String(websiteUrl) : null;
    if (instagramUrl !== undefined) updates.instagramUrl = instagramUrl ? String(instagramUrl) : null;
    if (coverUrl !== undefined) updates.coverUrl = coverUrl ? String(coverUrl) : null;
    try {
      // Explicit operator Replace from the admin Logo dialog — bypass
      // the storage-level lock guard. Automated callers (favicon
      // backfill, future re-scrape enrichment) MUST NOT pass this flag.
      const l = await storage.updateLabel(id, { ...updates, __bypassLogoLock: true });
      if (!l) return res.status(404).json({ message: "Label not found" });
      return res.json(l);
    } catch (err: any) {
      // Map the postgres unique-violation on `labels.domain` to a real 409
      // — same shape as the vendors PUT — so the client can show "another
      // label already uses this domain" instead of a generic 500.
      if (err?.code === "23505") {
        return res.status(409).json({ message: "Another label is already using that domain" });
      }
      throw err;
    }
  });
  app.delete("/api/admin/labels/:id", requireAdmin, async (req, res) => {
    {
      const id = String(req.params.id);
      const { partnerEditGate, createPendingChange } = await import("./auth/partnerPermissions");
      const outcome = await partnerEditGate(req, res, "edit_metadata", { kind: "label", id });
      if (outcome === "deny") return;
      if (outcome === "divert") {
        const row = await createPendingChange({
          targetTable: "labels", targetId: id, albumId: null,
          scopeKind: "label", scopeId: id,
          patch: { __op: "delete" },
          submittedByUserId: req.session.userId!,
        });
        return res.status(202).json({ pendingChange: row, message: "Your edit was sent to GoodTunes for review." });
      }
    }
    // SET NULL on albums.label_id — releases stay, label credit clears.
    await storage.deleteLabel(String(req.params.id), req.session.userId ?? null);
    return res.json({ message: "Deleted" });
  });

  // ─── Task #1425 — Manager ENTITY CRUD ─────────────────────────────
