  // ----- Play analytics ---------------------------------------------------
  // Backed by `analytics_events` table now (was in-memory ring buffer). Same
  // shape on the wire.
  app.post("/api/events", async (req, res) => {
    const userId = await getUserIdFromRequest(req);
    const events = Array.isArray(req.body?.events) ? req.body.events : [];
    const now = Date.now();
    const geo = geoFromRequest(req);
    // Build the full envelope server-side so the DB row + the PostHog
    // forward see the same shape. Geo overrides whatever the client
    // sent (clients can't be trusted to honestly self-report country).
    const enriched = events
      .filter((e: any) => e && typeof e.name === "string")
      .map((e: any) => {
        const ts = new Date(typeof e.ts === "number" ? e.ts : now);
        const deviceId = e.deviceId ? String(e.deviceId) : null;
        const sessionId = e.sessionId ? String(e.sessionId) : null;
        const platform = e.platform ? String(e.platform) : null;
        const referrer = e.referrer ? String(e.referrer) : null;
        // Campaign attribution — client-set, first-touch per session. Cap
        // each at 256 chars defensively (the client already trims). These
        // are campaign tags, not user identifiers, so no extra PII gate is
        // needed beyond keeping them out of the indexable top-level columns.
        const attr = (k: string): string | null => {
          const v = e[k];
          return v != null && String(v).trim() ? String(v).trim().slice(0, 256) : null;
        };
        const utmSource = attr("utmSource");
        const utmMedium = attr("utmMedium");
        const utmCampaign = attr("utmCampaign");
        const utmContent = attr("utmContent");
        const utmTerm = attr("utmTerm");
        const gclid = attr("gclid");
        const fbclid = attr("fbclid");
        const referrerHost = attr("referrerHost");
        const payload = e.payload && typeof e.payload === "object" ? e.payload : {};
        // Mirror the envelope fields into the persisted payload so the
        // analytics_events table is self-contained (one row → one event
        // with full context) without needing extra columns. The top-level
        // columns (sessionId / userId / clientId) stay populated too for
        // index-able lookups.
        const fullPayload = {
          ...payload,
          _device_id: deviceId,
          _platform: platform,
          _referrer: referrer,
          _country: geo.country,
          _region: geo.region,
          // Campaign attribution mirrored into the payload jsonb so a single
          // analytics_events query can GROUP BY source without joins. Only
          // written when present so events stay compact.
          ...(utmSource ? { _utm_source: utmSource } : {}),
          ...(utmMedium ? { _utm_medium: utmMedium } : {}),
          ...(utmCampaign ? { _utm_campaign: utmCampaign } : {}),
          ...(utmContent ? { _utm_content: utmContent } : {}),
          ...(utmTerm ? { _utm_term: utmTerm } : {}),
          ...(gclid ? { _gclid: gclid } : {}),
          ...(fbclid ? { _fbclid: fbclid } : {}),
          ...(referrerHost ? { _referrer_host: referrerHost } : {}),
        };
        return {
          clientId: e.id ? String(e.id) : undefined,
          name: String(e.name),
          payload: fullPayload,
          ts,
          sessionId: sessionId ?? undefined,
          userId,
          deviceId,
          platform,
          referrer,
          country: geo.country,
          region: geo.region,
        };
      });

    if (enriched.length) {
      // Postgres is the canonical, reconcilable store for analytics; if the
      // insert fails we MUST surface a non-2xx so the client keeps the batch
      // queued and retries on the next flush. Swallowing the error and
      // returning 204 would silently drop events from analytics_events while
      // PostHog still received them — divergent state we can't reconcile.
      try {
        await storage.insertAnalyticsEvents(enriched.map((e: any) => ({
          clientId: e.clientId,
          name: e.name,
          payload: e.payload,
          ts: e.ts,
          sessionId: e.sessionId,
          userId: e.userId,
        })));
      } catch (err) {
        console.error("[analytics] insert failed", err);
        return res.status(503).json({ message: "Analytics persistence unavailable; retry later" });
      }
      // Only forward to PostHog AFTER the canonical write succeeded. Still
      // fire-and-forget (no await) — a PostHog outage must not turn into a
      // 5xx on our ingest — but a Postgres failure now short-circuits before
      // we get here, so PostHog can never see events that aren't also in
      // analytics_events.
      void forwardToPostHog(enriched.map((e: any) => ({
        name: e.name,
        payload: e.payload,
        ts: e.ts,
        sessionId: e.sessionId ?? null,
        userId: e.userId ?? null,
        clientId: e.clientId ?? null,
        deviceId: e.deviceId,
        platform: e.platform,
        referrer: e.referrer,
        country: e.country,
        region: e.region,
      })));
    }
    return res.status(204).end();
  });

